// FUNDAMENTALDATEN AUFBEREITEN & SPEICHERN v3 – FastAPI Flat-JSON
// Modus: runOnceForAllItems
// Unterstützt drei Eingabeformate:
//   1. item.json.ticker vorhanden → direktes Flat-JSON
//   2. item.json.body ist Objekt  → Flat-JSON unter body
//   3. item.json.body ist String  → JSON.parse(body)

const items = $input.all();
const ergebnisse = [];
const heute       = new Date().toISOString().substring(0, 10);
const zeitstempel = new Date().toISOString();

const sd = $getWorkflowStaticData('global');
if (!sd.fundamentaldaten) sd.fundamentaldaten = {};

function fmt(v, digits) {
  const n = Number(v);
  if (v == null || v === '' || isNaN(n)) return 'k.A.';
  return n.toFixed(digits);
}
function fmtMrd(v) {
  const n = Number(v);
  if (v == null || v === '' || isNaN(n)) return 'k.A.';
  return (n / 1e9).toFixed(1) + ' Mrd.';
}
function fmtStr(v) {
  if (v == null || v === '') return 'k.A.';
  return String(v);
}

function parseRaw(item) {
  const j = item.json;
  // Fall 1: direktes Flat-JSON
  if (j && j.ticker) return j;
  // Fall 2 + 3: body
  if (j && j.body != null) {
    if (typeof j.body === 'object') return j.body;
    if (typeof j.body === 'string') {
      try { return JSON.parse(j.body); } catch(e) {}
    }
  }
  return {};
}

for (const item of items) {
  const raw = parseRaw(item);

  // Ticker/Name aus Watchlist als Fallback
  let wlTicker = '', wlName = '';
  try {
    const wl = $('Watchlist laden (Fundamental)').item.json;
    wlTicker = wl.ticker || '';
    wlName   = wl.name   || '';
  } catch(e) {}

  const finalTicker = String(raw.ticker || wlTicker || 'unbekannt').trim();
  const rawName     = fmtStr(raw.name);
  const finalName   = (rawName !== 'k.A.') ? rawName : (wlName || finalTicker);

  const hatEchteDaten = (
    raw.ticker &&
    raw.status === 'ok' &&
    (raw.kgv != null || raw.kgvForward != null || raw.marktkapitalisierung != null)
  );

  if (!hatEchteDaten) {
    const fehlerMsg = (raw.fehler && raw.fehler !== '')
      ? String(raw.fehler)
      : 'Keine Fundamentaldaten im Input des Aufbereitungs-Nodes gefunden.';
    ergebnisse.push({ json: {
      ticker: finalTicker, name: finalName,
      kgv:'', kgvForward:'', kbv:'', dividendeRendite:'', dividendeJe:'',
      exDividendeDatum:'', dividendenDatum:'', naechsterBericht:'', beta:'',
      marktkapitalisierung:'', verschuldungsgrad:'', eigenkapitalrendite:'',
      gewinnmarge:'', kursziel:'', empfehlung:'', regularMarketPrice:'',
      waehrung:'', exchange:'', sector:'', industry:'',
      zeitstempel, datum: heute, quelle: 'FastAPI/yfinance',
      status: 'fehler', fehler: fehlerMsg,
      letzter_fehler_zeitpunkt: zeitstempel,
      _nur_status_update: true
    }});
    continue;
  }

  const waehrung = raw.currency || raw.waehrung || 'EUR';

  // Dividendenrendite: FastAPI liefert bereits als Prozent (z.B. 1.65)
  let divRendite = 'k.A.';
  if (raw.dividendeRendite != null && raw.dividendeRendite !== '') {
    divRendite = Number(raw.dividendeRendite).toFixed(2) + '%';
  }

  // eigenkapitalrendite kommt als Dezimalzahl (0.163 = 16.3%)
  let eigenKap = 'k.A.';
  if (raw.eigenkapitalrendite != null && raw.eigenkapitalrendite !== '') {
    const v = Number(raw.eigenkapitalrendite);
    eigenKap = (!isNaN(v) ? (v * 100).toFixed(1) : 'k.A.') + '%';
  }

  // gewinnmarge kommt als Dezimalzahl (0.195 = 19.5%)
  let gewinnM = 'k.A.';
  if (raw.gewinnmarge != null && raw.gewinnmarge !== '') {
    const v = Number(raw.gewinnmarge);
    gewinnM = (!isNaN(v) ? (v * 100).toFixed(1) : 'k.A.') + '%';
  }

  // verschuldungsgrad direkt als Zahl (z.B. 17.3)
  let verschuld = 'k.A.';
  if (raw.verschuldungsgrad != null && raw.verschuldungsgrad !== '') {
    const v = Number(raw.verschuldungsgrad);
    verschuld = (!isNaN(v) ? v.toFixed(1) : 'k.A.') + '%';
  }

  const out = {
    ticker:               finalTicker,
    name:                 finalName,
    kgv:                  fmt(raw.kgv, 1),
    kgvForward:           fmt(raw.kgvForward, 1),
    kbv:                  fmt(raw.kbv, 2),
    dividendeRendite:     divRendite,
    dividendeJe:          (raw.dividendeJe != null && raw.dividendeJe !== '')
                            ? fmt(raw.dividendeJe, 2) + ' ' + waehrung : 'k.A.',
    exDividendeDatum:     fmtStr(raw.exDividendeDatum),
    dividendenDatum:      fmtStr(raw.dividendenDatum),
    naechsterBericht:     fmtStr(raw.naechsterBericht || ''),
    beta:                 fmt(raw.beta, 2),
    marktkapitalisierung: fmtMrd(raw.marktkapitalisierung),
    verschuldungsgrad:    verschuld,
    eigenkapitalrendite:  eigenKap,
    gewinnmarge:          gewinnM,
    kursziel:             fmt(raw.kursziel, 2),
    empfehlung:           fmtStr(raw.empfehlung),
    regularMarketPrice:   fmt(raw.regularMarketPrice, 2),
    waehrung,
    exchange:             fmtStr(raw.exchange),
    sector:               fmtStr(raw.sector),
    industry:             fmtStr(raw.industry),
    zeitstempel,
    datum:                heute,
    quelle:               fmtStr(raw.quelle || 'FastAPI/yfinance'),
    status:               'ok',
    fehler:               '',
    letzter_fehler_zeitpunkt: '',
    _nur_status_update:   false
  };

  sd.fundamentaldaten[finalTicker] = out;
  ergebnisse.push({ json: out });
}

return ergebnisse;

// FUNDAMENTALDATEN ROUTING – Run Once for All Items
// Input: vorhandene DB-Zeilen aus "DB: Fundamental suchen"
// Quelle: frische Fundamentaldaten aus "Fundamentaldaten aufbereiten & speichern"

const dbRowsRaw = $input.all()
  .map(item => item.json || {})
  .filter(row => row.ticker);

const dbByTicker = {};

for (const row of dbRowsRaw) {
  const ticker = String(row.ticker || '').trim();
  if (!ticker) continue;

  // Falls derselbe Ticker mehrfach vorhanden ist, nimm bevorzugt den mit ID.
  if (!dbByTicker[ticker] || row.id) {
    dbByTicker[ticker] = row;
  }
}

const sourceItems = $('Fundamentaldaten aufbereiten & speichern').all();

return sourceItems.map(item => {
  const source = item.json || {};
  const ticker = String(source.ticker || '').trim();
  const existing = dbByTicker[ticker];

  const rowExists =
    existing &&
    existing.id !== undefined &&
    existing.id !== null &&
    String(existing.id).trim() !== '';

  return {
    json: {
      ...source,
      _existing_id: rowExists ? String(existing.id) : '',
      _rowExists: Boolean(rowExists)
    }
  };
});

